<?php
/**
 * FSIA home page (fsia.in) — built from the fsia-home-clone- React app.
 *
 * - Page HTML is pre-rendered (full content visible to Google without JS).
 * - React then hydrates it from /fsia-home-assets/ for sliders, modals, search, etc.
 * - Also handles the "AI testimonial" POST that the Node server.ts used to handle.
 *
 * Upload together with the /fsia-home-assets/ folder (same directory level).
 */

// Optional: set a Gemini key here (or as the GEMINI_API_KEY env var) for live AI testimonials.
// Leave empty to always return the curated editorial text.
if (!defined('FSIA_GEMINI_API_KEY')) define('FSIA_GEMINI_API_KEY', getenv('GEMINI_API_KEY') ?: '');
if (!defined('FSIA_GEMINI_MODEL'))   define('FSIA_GEMINI_MODEL', 'gemini-2.5-flash');

$FSIA_ASSET_DIR = '/fsia-home-assets';

/* ---------- AI testimonial endpoint (replaces /api/generate-testimonial) ---------- */
if (($_GET['api'] ?? '') === 'generate-testimonial') {
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
        http_response_code(405);
        echo json_encode(['error' => 'POST only']);
        exit;
    }

    $in = json_decode(file_get_contents('php://input'), true);
    if (!is_array($in)) $in = [];
    $clean = function ($k, $def) use ($in) {
        $v = isset($in[$k]) ? trim(strip_tags((string)$in[$k])) : '';
        $v = mb_substr($v, 0, 120);
        return $v !== '' ? $v : $def;
    };
    $name     = $clean('name', 'Contestant');
    $title    = $clean('title', 'National Winner');
    $category = $clean('category', 'Forever Miss/Mrs India');
    $location = $clean('location', 'India');
    $season   = $clean('season', '2025');

    $fallback = [
        'quote'  => "Winning {$title} at Forever Star India was a defining milestone. Representing {$location} on the national stage transformed my confidence, voice, and leadership vision.",
        'story'  => 'From local auditions to the grand Zee Studio coronation in Jaipur, FSIA offered unmatched grooming, stage presence coaching, and verifiable national recognition under Government of India Class 41 registered trademark.',
        'advice' => 'Believe in your authenticity and let your purpose guide every step on the national runway.',
        'source' => 'curated-editorial',
    ];

    if (FSIA_GEMINI_API_KEY === '' || !function_exists('curl_init')) {
        echo json_encode($fallback);
        exit;
    }

    $prompt = "You are the official editorial biographer for the Forever Star India Awards & Pageants (FSIA), India's premier Class 41 registered national pageantry organization.\n"
        . "Write an authentic, inspiring first-person winner's testimonial and short transformation story for:\n"
        . "- Winner Name: {$name}\n- Title: {$title}\n- Category: {$category}\n- State/City: {$location}\n- Season: {$season}\n\n"
        . "Tone: Dignified, eloquent, inspiring, celebrating women empowerment, stage confidence, and the journey from city auditions to the grand coronation at Zee Studio Jaipur.\n\n"
        . "Return JSON in this exact structure:\n{\n  \"quote\": \"A 1-2 sentence impactful winning quotation in quotation marks\",\n  \"story\": \"A 2-3 sentence transformation story describing the audition, grooming, and stage triumph\",\n  \"advice\": \"A 1 sentence advice for aspiring delegates\"\n}";

    $ch = curl_init('https://generativelanguage.googleapis.com/v1beta/models/' . rawurlencode(FSIA_GEMINI_MODEL) . ':generateContent');
    curl_setopt_array($ch, [
        CURLOPT_POST           => true,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT        => 20,
        CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'x-goog-api-key: ' . FSIA_GEMINI_API_KEY],
        CURLOPT_POSTFIELDS     => json_encode([
            'contents'         => [['parts' => [['text' => $prompt]]]],
            'generationConfig' => ['responseMimeType' => 'application/json'],
        ]),
    ]);
    $raw  = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    $parsed = null;
    if ($raw !== false && $code === 200) {
        $res  = json_decode($raw, true);
        $text = $res['candidates'][0]['content']['parts'][0]['text'] ?? '';
        $parsed = json_decode($text, true);
    }
    if (!is_array($parsed) || empty($parsed['quote'])) {
        echo json_encode($fallback);
        exit;
    }
    echo json_encode([
        'quote'  => (string)$parsed['quote'],
        'story'  => (string)($parsed['story'] ?? $fallback['story']),
        'advice' => (string)($parsed['advice'] ?? $fallback['advice']),
        'source' => FSIA_GEMINI_MODEL,
    ]);
    exit;
}

/* ---------- Page ---------- */
$fsia_ver = function ($file) use ($FSIA_ASSET_DIR) {
    $path = $_SERVER['DOCUMENT_ROOT'] . $FSIA_ASSET_DIR . '/' . $file;
    return is_file($path) ? filemtime($path) : '1';
};
/* ---------- Homepage CMS data (edited in /cms-admin/ → Homepage) ----------
 * Reads the hero slider, calendar, advertisement, social profiles and celebrity
 * guests from the CMS database and hands them to the React app as
 * window.__FSIA_CMS__. A section that was never saved is simply missing, and the
 * app shows its built-in content. Any problem (no config, DB down) = same thing.
 */
$fsia_cms_json = '{}';
try {
    $fsia_cms_cfg_file = __DIR__ . '/cms/backend/config.php';
    if (is_file($fsia_cms_cfg_file)) {
        $fsia_cms_cfg = require $fsia_cms_cfg_file;
        $c = $fsia_cms_cfg['db'] ?? null;
        if (is_array($c)) {
            $pdo = new PDO(
                sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4', $c['host'], (int) ($c['port'] ?? 3306), $c['name']),
                $c['user'],
                $c['password'],
                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES => false, PDO::ATTR_TIMEOUT => 3]
            );
            $st = $pdo->prepare(
                "SELECT section_key, content FROM page_sections
                 WHERE page_slug = 'index'
                   AND section_key IN ('hero_slides', 'calendar_events', 'advertisement', 'social_profiles', 'celebrities')"
            );
            $st->execute();
            $fsia_cms = [];
            foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $row) {
                $content = json_decode((string) $row['content'], true);
                if (is_array($content)) {
                    $fsia_cms[$row['section_key']] = ['content' => $content]; // same shape as the CMS API
                }
            }
            if ($fsia_cms) {
                // HEX flags: the JSON can never close the <script> tag or break out of it.
                $fsia_cms_json = json_encode($fsia_cms, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: '{}';
            }
            $pdo = null;
        }
    }
} catch (Throwable $e) {
    error_log('FSIA homepage CMS: ' . $e->getMessage());
    $fsia_cms_json = '{}';
}
unset($fsia_cms_cfg, $fsia_cms_cfg_file, $c);

header('Content-Type: text/html; charset=utf-8');
?>
